/**
 * Mapping from life situation to journey level
 */
const lifeSituationToJourneyLevel: Record<string, string> = {
  "Exploring": "Beginner",
  "Deepening": "Intermediate",
  "Advanced Study": "Advanced",
  "Crisis": "Crisis Navigation"
};

/**
 * Calculate match score between user preferences and a guide
 */
function calculateMatchScore(guide: SpiritualGuide, prefs: MatchingPreferences): number {
  let score = 0;

  // FAITH MATCH (CRITICAL - 40 points max)
  // If faithPreference is specified, it's a REQUIRED match
  if (prefs.faithPreference) {
    const userFaith = prefs.faithPreference.toLowerCase();
    const guideFaith = guide.faith.toLowerCase();

    // Handle variations in faith names
    if (userFaith.includes('sunni') || userFaith.includes('shia') || userFaith.includes('sufi')) {
      if (!guideFaith.includes('islam')) return 0; // MUST be Islam
    } else if (userFaith === 'islam' || userFaith.includes('islam')) {
      if (!guideFaith.includes('islam')) return 0; //  MUST be Islam
    } else {
      if (userFaith !== guideFaith && !guideFaith.includes(userFaith)) {
        return 0; // Faith mismatch is disqualifying
      }
    }
    score += 40; // Faith match
  }

  // SPIRITUAL GOALS (30 points max)
  if (prefs.spiritualGoals) {
    prefs.spiritualGoals.forEach(goal => {
      if (guide.specialties.some(spec => spec.toLowerCase().includes(goal.toLowerCase()))) {
        score += 6;
      }
    });
  }

  // GUIDE ROLE (10 points)
  if (prefs.guideRole && guide.archetypeRoles) {
    if (guide.archetypeRoles.some(role => role.toLowerCase().includes(prefs.guideRole.toLowerCase()))) {
      score += 10;
    }
  }

  // AGE PREFERENCE (5 points)
  if (prefs.agePreference && guide.ageGroup === prefs.agePreference) {
    score += 5;
  }

  // LIFE SITUATION MATCH (10 points)
  if (prefs.lifeSituation && guide.journeyLevel) {
    const targetLevel = lifeSituationToJourneyLevel[prefs.lifeSituation];
    if (targetLevel && guide.journeyLevel.includes(targetLevel)) {
      score += 10;
    }
  }

  // SECT/TRADITION FOCUS (5 points)
  if (prefs.sectFocus && guide.sect) {
    prefs.sectFocus.forEach(sect => {
      if (guide.sect.some(guideSect => guideSect.toLowerCase().includes(sect.toLowerCase()))) {
        score += 5;
      }
    });
  }

  return score;
}

/**
 * Match user to guide and return the best match
 */
export function matchUserToGuide(prefs: MatchingPreferences): SpiritualGuide {
  const scoredGuides = guides.map(guide => ({
    guide,
    score: calculateMatchScore(guide, prefs)
  }));
  
  scoredGuides.sort((a, b) => b.score - a.score);
  
  // Log top 3 matches for debugging
  console.log('[Guide Matching] User preferences:', prefs);
  console.log('[Guide Matching] Top 3 matches:');
  scoredGuides.slice(0, 3).forEach((match, idx) => {
    console.log(`  ${idx + 1}. ${match.guide.name} (${match.guide.faith}, ${match.guide.role}): ${match.score} points`);
  });
  
  return scoredGuides[0].guide;
}

/**
 * COMBINED GUIDES ARRAY - Includes all guides from main and additional files
 * This is the single source of truth for all guide matching
 */
export const guides: SpiritualGuide[] = [
  ...mainGuides,
  ...additionalGuides
];

/**
 * Rank all guides for a user
 */
export function rankGuides(prefs: MatchingPreferences): Array<{guide: SpiritualGuide, score: number}> {
  const scoredGuides = guides.map(guide => ({
    guide,
    score: calculateMatchScore(guide, prefs)
  }));
  
  scoredGuides.sort((a, b) => b.score - a.score);
  
  return scoredGuides;
}